--
-- Name: date_key(date); Type: FUNCTION; Schema: analytics; Owner: wms_user
--

CREATE FUNCTION analytics.date_key(p_date date) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT TO_CHAR(p_date,'YYYYMMDD')::INTEGER;
$$;


ALTER FUNCTION analytics.date_key(p_date date) OWNER TO wms_user;

--
-- Name: etl_create_next_fact_partitions(integer); Type: FUNCTION; Schema: analytics; Owner: wms_user
--

CREATE FUNCTION analytics.etl_create_next_fact_partitions(p_months_ahead integer DEFAULT 3) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_month DATE;
    v_next  DATE;
    v_name  TEXT;
    v_count INT := 0;
    v_tables TEXT[] := ARRAY[
        'fact_inventory_movements',
        'fact_stock_snapshot',
        'fact_billing_transactions',
        'fact_tasks'
    ];
    tbl TEXT;
BEGIN
    FOR i IN 1..p_months_ahead LOOP
        v_month := DATE_TRUNC('month', NOW() + (i || ' months')::INTERVAL)::DATE;
        v_next  := (v_month + INTERVAL '1 month')::DATE;
        FOREACH tbl IN ARRAY v_tables LOOP
            v_name := tbl || '_' || TO_CHAR(v_month,'YYYY_MM');
            IF NOT EXISTS (SELECT 1 FROM pg_tables WHERE schemaname='analytics' AND tablename=v_name) THEN
                EXECUTE format(
                    'CREATE TABLE analytics.%I PARTITION OF analytics.%I FOR VALUES FROM (%L) TO (%L)',
                    v_name, tbl, v_month, v_next
                );
                v_count := v_count + 1;
            END IF;
        END LOOP;
    END LOOP;
    RETURN v_count;
END;
$$;


ALTER FUNCTION analytics.etl_create_next_fact_partitions(p_months_ahead integer) OWNER TO wms_user;

--
-- Name: etl_load_fact_billing_transactions(date); Type: FUNCTION; Schema: analytics; Owner: wms_user
--

CREATE FUNCTION analytics.etl_load_fact_billing_transactions(p_watermark date DEFAULT NULL::date) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_wm    DATE;
    v_count INT := 0;
BEGIN
    SELECT COALESCE(p_watermark,
        (SELECT last_loaded_at::DATE FROM analytics.etl_watermarks WHERE table_name = 'fact_billing_transactions'))
    INTO   v_wm;

        service_date, date_key, company_key, order_key,
        charge_type, quantity, unit_price, amount,
        invoice_id, is_invoiced, oltp_billing_tx_id, oltp_billing_tx_date
    )
    SELECT
        bt.service_date,
        analytics.date_key(bt.service_date),
        dc.company_key,
        dord.order_key,
        bt.charge_type::TEXT,
        bt.quantity,
        bt.unit_price,
        bt.amount,
        bt.invoice_id,
        bt.invoice_id IS NOT NULL,
        bt.id,
        bt.service_date
    FROM   public.billing_transactions bt
    JOIN   analytics.dim_company dc   ON dc.company_id = bt.company_id AND dc.is_current
    LEFT   JOIN analytics.dim_order dord ON dord.order_id = bt.reference_id
    WHERE  bt.service_date >= v_wm
    ON     CONFLICT DO NOTHING;

    GET DIAGNOSTICS v_count = ROW_COUNT;

    UPDATE analytics.etl_watermarks
    SET    last_loaded_at = NOW(), last_run_at = NOW(), rows_loaded = rows_loaded + v_count, status = 'idle'
    WHERE  table_name = 'fact_billing_transactions';

    RETURN v_count;
END;
$$;


ALTER FUNCTION analytics.etl_load_fact_billing_transactions(p_watermark date) OWNER TO wms_user;

