--
-- Name: fn_create_next_audit_partitions(integer); Type: FUNCTION; Schema: public; Owner: wms_user
--

CREATE FUNCTION public.fn_create_next_audit_partitions(p_quarters_ahead integer DEFAULT 2) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_qstart DATE;
    v_qend   DATE;
    v_name   TEXT;
    v_count  INT := 0;
BEGIN
    FOR i IN 1..p_quarters_ahead LOOP
        v_qstart := DATE_TRUNC('quarter', NOW() + (i || ' quarter')::INTERVAL)::DATE;
        v_qend   := (v_qstart + INTERVAL '3 months')::DATE;
        v_name   := 'audit_logs_' || TO_CHAR(v_qstart,'YYYY') || '_q' || TO_CHAR(v_qstart,'Q');
        IF NOT EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = v_name) THEN
            EXECUTE format(
                'CREATE TABLE %I PARTITION OF audit_logs FOR VALUES FROM (%L) TO (%L)',
                v_name, v_qstart, v_qend
            );
            v_count := v_count + 1;
        END IF;
    END LOOP;
    RETURN v_count;
END;
$$;


ALTER FUNCTION public.fn_create_next_audit_partitions(p_quarters_ahead integer) OWNER TO wms_user;

--
-- Name: fn_create_next_partitions(integer); Type: FUNCTION; Schema: public; Owner: wms_user
--

CREATE FUNCTION public.fn_create_next_partitions(p_months_ahead integer DEFAULT 3) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_month DATE;
    v_next  DATE;
    v_name  TEXT;
    v_count INT := 0;
BEGIN
    FOR i IN 1..p_months_ahead LOOP
        v_month := DATE_TRUNC('month', NOW() + (i || ' months')::INTERVAL)::DATE;
        v_next  := (v_month + INTERVAL '1 month')::DATE;

        v_name := 'inventory_ledger_' || TO_CHAR(v_month, 'YYYY_MM');
        IF NOT EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = v_name) THEN
            EXECUTE format(
                'CREATE TABLE %I PARTITION OF inventory_ledger FOR VALUES FROM (%L) TO (%L)',
                v_name, v_month, v_next
            );
            v_count := v_count + 1;
        END IF;

        v_name := 'billing_transactions_' || TO_CHAR(v_month, 'YYYY_MM');
        IF NOT EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = v_name) THEN
            EXECUTE format(
                'CREATE TABLE %I PARTITION OF billing_transactions FOR VALUES FROM (%L) TO (%L)',
                v_name, v_month, v_next
            );
            v_count := v_count + 1;
        END IF;
    END LOOP;
    RETURN v_count;
END;
$$;


ALTER FUNCTION public.fn_create_next_partitions(p_months_ahead integer) OWNER TO wms_user;

--
-- Name: fn_guard_received_quantity(); Type: FUNCTION; Schema: public; Owner: wms_user
--

CREATE FUNCTION public.fn_guard_received_quantity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.received_quantity > NEW.expected_quantity * 1.10 THEN
        RAISE EXCEPTION
            'received_quantity (%) exceeds 110%% of expected_quantity (%) on line %',
            NEW.received_quantity, NEW.expected_quantity, NEW.id;
    END IF;
    RETURN NEW;
END;
$$;


