--
-- Name: current_stock; Type: TABLE; Schema: public; Owner: wms_user
--

CREATE TABLE public.current_stock (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    product_id uuid NOT NULL,
    location_id uuid NOT NULL,
    warehouse_id uuid NOT NULL,
    lot_id uuid,
    package_id uuid,
    quantity_on_hand numeric(15,4) DEFAULT 0 NOT NULL,
    quantity_reserved numeric(15,4) DEFAULT 0 NOT NULL,
    quantity_available numeric(15,4) GENERATED ALWAYS AS ((quantity_on_hand - quantity_reserved)) STORED,
    status public.stock_status DEFAULT 'available'::public.stock_status NOT NULL,
    version integer DEFAULT 0 NOT NULL,
    last_movement_at timestamp with time zone,
    CONSTRAINT chk_qty_non_negative CHECK ((quantity_on_hand >= (0)::numeric)),
    CONSTRAINT chk_reserved_lte_on_hand CHECK ((quantity_reserved <= quantity_on_hand)),
    CONSTRAINT chk_reserved_non_negative CHECK ((quantity_reserved >= (0)::numeric))
)
WITH (autovacuum_vacuum_scale_factor='0.02', autovacuum_analyze_scale_factor='0.01');

