--
-- Name: fn_recompute_invoice_totals(uuid); Type: FUNCTION; Schema: public; Owner: wms_user
--

CREATE FUNCTION public.fn_recompute_invoice_totals(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_sub  DECIMAL(14,2);
    v_rate DECIMAL(5,4);
    v_tax  DECIMAL(14,2);
BEGIN
    SELECT COALESCE(SUM(amount), 0) INTO v_sub
    FROM   invoice_lines WHERE invoice_id = p_invoice_id;
    SELECT tax_rate INTO v_rate FROM invoices WHERE id = p_invoice_id;
    v_tax := ROUND(v_sub * v_rate, 2);
    UPDATE invoices
    SET    subtotal   = v_sub,
           tax_amount = v_tax,
           total      = v_sub + v_tax
    WHERE  id = p_invoice_id AND status = 'draft';
END;
$$;


ALTER FUNCTION public.fn_recompute_invoice_totals(p_invoice_id uuid) OWNER TO wms_user;

--
-- Name: fn_reconcile_reservations(); Type: FUNCTION; Schema: public; Owner: wms_user
--

CREATE FUNCTION public.fn_reconcile_reservations() RETURNS TABLE(company_id uuid, product_id uuid, location_id uuid, lot_id uuid, stored_reserved numeric, actual_sum numeric, drift numeric)
    LANGUAGE sql
    AS $$
    SELECT
        cs.company_id, cs.product_id, cs.location_id, cs.lot_id,
        cs.quantity_reserved                        AS stored_reserved,
        COALESCE(rs.active_sum, 0)                  AS actual_sum,
        cs.quantity_reserved - COALESCE(rs.active_sum, 0) AS drift
    FROM   current_stock cs
    LEFT   JOIN (
        SELECT company_id, product_id, location_id, lot_id,
               SUM(quantity) AS active_sum
        FROM   stock_reservations
        WHERE  status = 'active'
        GROUP  BY company_id, product_id, location_id, lot_id
    ) rs USING (company_id, product_id, location_id, lot_id)
    WHERE  ABS(cs.quantity_reserved - COALESCE(rs.active_sum, 0)) > 0.001;
$$;


ALTER FUNCTION public.fn_reconcile_reservations() OWNER TO wms_user;

