--
-- Name: fact_inbound_operations; Type: TABLE; Schema: analytics; Owner: wms_user
--

CREATE TABLE analytics.fact_inbound_operations (
    inbound_op_key bigint NOT NULL,
    confirmed_date_key integer,
    completed_date_key integer,
    arrival_date_key integer,
    company_key bigint NOT NULL,
    warehouse_key bigint,
    order_key bigint,
    status text NOT NULL,
    total_lines integer DEFAULT 0 NOT NULL,
    total_expected_qty numeric(15,4) DEFAULT 0 NOT NULL,
    total_received_qty numeric(15,4) DEFAULT 0 NOT NULL,
    discrepancy_lines integer DEFAULT 0 NOT NULL,
    fill_rate_pct numeric(7,4) GENERATED ALWAYS AS (
CASE
    WHEN (total_expected_qty > (0)::numeric) THEN round(((total_received_qty / total_expected_qty) * (100)::numeric), 4)
    ELSE NULL::numeric
END) STORED,
    days_to_complete numeric(10,2),
    is_on_time boolean,
    oltp_inbound_order_id uuid NOT NULL,
    completed_at timestamp with time zone,
    loaded_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE analytics.fact_inbound_operations OWNER TO wms_user;

--
-- Name: fact_inbound_operations_inbound_op_key_seq; Type: SEQUENCE; Schema: analytics; Owner: wms_user
--

ALTER TABLE analytics.fact_inbound_operations ALTER COLUMN inbound_op_key ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME analytics.fact_inbound_operations_inbound_op_key_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


