--
-- Name: v_analytics_wh_task_completed_rows; Type: VIEW; Schema: public; Owner: wms_user
--

CREATE VIEW public.v_analytics_wh_task_completed_rows AS
 SELECT wt.id AS task_id,
    wi.company_id,
    wi.warehouse_id,
    (wt.task_type)::text AS task_type,
    wt.started_at,
    wt.completed_at,
        CASE
            WHEN ((wt.started_at IS NOT NULL) AND (wt.completed_at IS NOT NULL)) THEN (EXTRACT(epoch FROM (wt.completed_at - wt.started_at)) / 60.0)
            ELSE NULL::numeric
        END AS duration_minutes
   FROM (public.warehouse_tasks wt
     JOIN public.workflow_instances wi ON ((wi.id = wt.workflow_instance_id)))
  WHERE ((wt.status = 'completed'::public.warehouse_task_status) AND (wt.completed_at IS NOT NULL));


ALTER VIEW public.v_analytics_wh_task_completed_rows OWNER TO wms_user;

