--
-- Name: v_wms_worker_load; Type: VIEW; Schema: public; Owner: wms_user
--

CREATE VIEW public.v_wms_worker_load AS
 SELECT w.id AS worker_id,
    w.display_name AS full_name,
    (count(DISTINCT
        CASE
            WHEN (wt.status = 'in_progress'::public.warehouse_task_status) THEN wt.id
            ELSE NULL::uuid
        END))::integer AS in_progress_count,
    (count(DISTINCT
        CASE
            WHEN (wt.status = 'assigned'::public.warehouse_task_status) THEN wt.id
            ELSE NULL::uuid
        END))::integer AS assigned_pending_count,
    (((count(DISTINCT
        CASE
            WHEN (wt.status = 'in_progress'::public.warehouse_task_status) THEN wt.id
            ELSE NULL::uuid
        END) * 3) + count(DISTINCT
        CASE
            WHEN (wt.status = 'assigned'::public.warehouse_task_status) THEN wt.id
            ELSE NULL::uuid
        END)))::integer AS load_score
   FROM ((public.workers w
     LEFT JOIN public.task_assignments ta ON (((ta.worker_id = w.id) AND (ta.unassigned_at IS NULL))))
     LEFT JOIN public.warehouse_tasks wt ON (((wt.id = ta.task_id) AND (wt.status = ANY (ARRAY['assigned'::public.warehouse_task_status, 'in_progress'::public.warehouse_task_status])))))
  GROUP BY w.id, w.display_name;


ALTER VIEW public.v_wms_worker_load OWNER TO wms_user;

--
-- Name: v_worker_load; Type: VIEW; Schema: public; Owner: wms_user
--

CREATE VIEW public.v_worker_load AS
 SELECT u.id AS worker_id,
    u.full_name,
    u.status,
    array_agg(DISTINCT uwr.role ORDER BY uwr.role) AS worker_roles,
    count(t.id) FILTER (WHERE (t.status = 'in_progress'::public.task_status)) AS in_progress_count,
    count(t.id) FILTER (WHERE (t.status = 'assigned'::public.task_status)) AS assigned_pending_count,
    (((count(t.id) FILTER (WHERE (t.status = 'in_progress'::public.task_status)) * 3) + count(t.id) FILTER (WHERE (t.status = 'assigned'::public.task_status))))::integer AS load_score
   FROM ((public.users u
     LEFT JOIN public.user_worker_roles uwr ON ((uwr.user_id = u.id)))
     LEFT JOIN public.tasks t ON (((t.assigned_to = u.id) AND (t.status = ANY (ARRAY['assigned'::public.task_status, 'in_progress'::public.task_status])))))
  WHERE ((u.role = 'wh_operator'::public.user_role) AND (u.status = 'active'::public.user_status))
  GROUP BY u.id, u.full_name, u.status;


ALTER VIEW public.v_worker_load OWNER TO wms_user;

